create or replace function public.get_video_view_counts() returns table(video_id uuid,view_count bigint) language sql stable security invoker set search_path='' as $$ select e.video_id,count(*)::bigint as view_count from public.video_events e join public.videos v on v.id=e.video_id where e.event_type='play' and v.status='published'::public.video_status and v.published_at<=now() group by e.video_id $$;
create or replace function public.get_trending_videos(p_since timestamptz default now()-interval '7 days',p_limit integer default 4) returns table(video_id uuid,recent_play_count bigint) language sql stable security invoker set search_path='' as $$ select e.video_id,count(*)::bigint as recent_play_count from public.video_events e join public.videos v on v.id=e.video_id where e.event_type='play' and e.occurred_at>=greatest(p_since,now()-interval '31 days') and v.status='published'::public.video_status and v.published_at<=now() group by e.video_id order by count(*) desc,e.video_id limit least(greatest(p_limit,1),20) $$;
